if (status === "loading") return <Spinner />
return (
  <>
    {error ? <Alert error={error} /> : <Results items={items} />}
    {items.length > 0 && <Summary items={items} />}
  </>
)

// Each row has an uncontrolled <input>. Prepending a todo with index keys
// leaves the typed text on the wrong row. Stable ids fix it:
todos.map(todo => <TodoRow key={todo.id} todo={todo} />)
